const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome', headless: 'new', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type()==='error') errors.push('CONSOLE: ' + m.text()); });

  await page.goto('http://localhost:8791/web/index.html', { waitUntil: 'networkidle2', timeout: 60000 });
  await page.waitForFunction(() => document.getElementById('boot')?.hidden, { timeout: 45000 });

  async function clickByText(text) {
    const buttons = await page.$$('button');
    for (const b of buttons) {
      const t = await page.evaluate(el => el.textContent, b);
      if (t.includes(text)) { await b.click(); return true; }
    }
    return false;
  }

  // Start new game
  await clickByText('Start New Game');
  await new Promise(r => setTimeout(r, 500));
  let text = await page.evaluate(() => document.body.innerText);
  console.log('--- after Start New Game ---');
  console.log(text.slice(0, 400));

  await browser.close();
